/* 创建临时请求并把其不可变快照交给现有 Future 执行层。 */
static xfuture* __xrtHttpClientEasyAsync(
	xhttpclient* pClient,
	xstrview Method,
	xstrview Url,
	const xbytesview* pBody,
	xstrview ContentType,
	const xhttpcalloptions* pOptions
)
{
	xhttprequest* pRequest;
	xfuture* pFuture;

	if ( !__xrtHttpClientEasyCheck(
		pClient,
		true,
		"submit-http-easy-future"
	) ) {
		return NULL;
	}
	pRequest = __xrtHttpClientEasyRequest(
		Method,
		Url,
		pBody,
		ContentType
	);
	if ( pRequest == NULL ) {
		return NULL;
	}
	pFuture = xrtHttpClientDoAsync(
		pClient,
		pRequest,
		pOptions
	);
	xrtHttpRequestDestroy(pRequest);
	return pFuture;
}



/* 创建临时请求并在宿主线程复用现有同步等待层。 */
static xhttpresult* __xrtHttpClientEasySync(
	xhttpclient* pClient,
	xstrview Method,
	xstrview Url,
	const xbytesview* pBody,
	xstrview ContentType,
	const xhttpcalloptions* pOptions
)
{
	xhttprequest* pRequest;
	xhttpresult* pResult;

	if ( !__xrtHttpClientEasyCheck(
		pClient,
		true,
		"run-http-easy-sync"
	) ) {
		return NULL;
	}
	pRequest = __xrtHttpClientEasyRequest(
		Method,
		Url,
		pBody,
		ContentType
	);
	if ( pRequest == NULL ) {
		return NULL;
	}
	pResult = xrtHttpClientDoSync(
		pClient,
		pRequest,
		pOptions
	);
	xrtHttpRequestDestroy(pRequest);
	return pResult;
}



